      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n20만)20~69세) 기아봉고,현대포터오픈베드 보유자_좌담회 사례비 20만원 11/1(일)참석가능하신분\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.22. 13:09\n조회 23\n구독\n20만)20~69세) 기아봉고,현대포터오픈베드 보유자_좌담회 사례비 20만원 11/1(일)참석가능하신분\n신청하신분은 재신청 안하셔도 됩니다\n기아 봉고/현대 포터 오픈베드 보유자 5명/ 11월1(일) 오후 5~7시\n엔진 형태 : 내연기관 3명, EV 2명\n향후 1년 이내 PV카고 , 스타리아 카고밴 , 봉고/포너 탑차 구입의향 있는 분\n현보유차 및 과거 봉고/포터 보유 기간 합산 5년 이상 (현 보유차 구매 시점 크게 상관 없음)\n주 5회 이상 적재용도로 사용, 1회 평균 적재량 700KG 이상\n(성별 무관 / 나이 20~69세)\n응답자 사례비는 - 20만원 입니다.\n장소: 서초구 인근\n신청시\n1.이름 / 연락처 / 성별 / 나이 / 결혼여부 / 자녀나이\n2.구매 브랜드 및 엔진타입 / 구매시기/구매시 기아 PV5 오픈베드 비교자 (비교모델 3순위 이내)\n예) 홍길동 / 010-0000-0000 / 남 / 35 / 미혼 / X // ◇◇◇◇◇◇ & / 구매 25년10월 / 비교모델\nhttps://forms.gle/f1f5BtmBumcscir47\n좋아요\n0\n송파구에서 많이 본 동네소식 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n10/26~27)만 75세~85세 남녀) (인천)제품 사용성 조사를 위한 소비자모집(제품 사용 후 1:1인터뷰)\n좌담회알바좌담회카페\n26.10.22.\n댓글\n0\n20만)20~69세) 기아봉고,현대포터오픈베드 보유자_좌담회 사례비 20만원 11/1(일)참석가능하신분\n좌담회알바좌담회카페\n26.10.22.\n댓글\n0\n고유링크) 91~07년생 만 19~35세 기혼여성 직장인 )탄산음료 맛테스트 설문조사\n좌담회알바좌담회카페\n26.10.22.\n댓글\n0\n고유링크) 91~07년생 만 19~35세 미혼여성 직장인 )탄산음료 맛테스트 설문조사\n좌담회알바좌담회카페\n26.10.22.\n댓글\n0\n수정&재공지 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
