      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n9-16kg, 4-5단계 팬티형 기저귀 사용하는 남아 자녀와 어머님 대상 [가정방문 인터뷰] 모집(*11/4 진행)\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.22. 15:13\n조회 23\n구독\n9-16kg, 4-5단계 팬티형 기저귀 사용하는 자녀와 어머님 대상 [가정방문 인터뷰] 모집(*11/4 진행)\n1. 일정\n11월 4일(수) 단 하루 진행 (추후 통화시 진행 시간 조율 가능)\n자택으로 직접 방문하는 가정 인터뷰입니다. <가정(자녀방 등) 공개 및 기저귀 교체하는 과정 등을 촬영하는 방식 포함>\n** 사용 브랜드 : 팸퍼스, 하기스 기저귀 주사용자\n** 사용 기저귀 크기 : 대형 (L, 4단계) 또는 특대형 (Extra Large, 5단계)\n** 신청 시 적어주신 정보를 보고 조건에 부합하시는 분들께 연락 드려 확정 및 일정 말씀드리겠습니다.\n** 사용하는 기저귀는 사전에 사진을 받고 있습니다\n2. 조사 방법\n진행자의 질문에 응답하는 형태의 자유롭게 이야기 나누는 인터뷰 입니다.\n평소 사용하는 자녀의 기저귀에 대해서 이야기 나누는 어렵지 않은 조사이니 많은 신청 부탁드립니다.\n3. 비용\n** 가정방문 인터뷰 최종 참여시 : 150,000원 지급\n(참여 이후 본인 계좌이체 예정이며 기타소득신고를 위한 개인정보 입력이 필수입니다)\n** 인터뷰 기록을 위해 녹음/녹화쵤영 진행, 외부반출X (보안동의서 작성/얼굴노출 거절 가능)\n** 방문인원 총 6명 (외국인 3명포함)\n1. 어머니성함:\n2. 어머니연락처:\n3. 엄마연령(생년월일):\n4. 거주지(구/동 까지):\n5. 자녀연령(생년월일):\n6. 자녀성별(남아/여아):\n7. 자녀의 체중(kg):\n8. 자녀의 키(cm):\n9. 자녀가 현재 사용하는 기저귀 크기 및 단계는? <대형(L, 4단계) 또는 특대형(Extra Large, 5단계) 사용자 대상>\n10. 하루 평균 몇 개의 기저귀를 어머님께서 직접 교체해주시나요? <5개 이상만 가능>\n11. 자녀가 하루 평균 어린이집/유치원에 다니는 시간은? <등원안함 가능>\nex) 등원함-4시간, 등원안함, 등원함-7시간 등\n12. 현재 가장 자주 사용하는 기저귀 브랜드와 세부 제품명, 단계(크기)는 무엇인가요? <제품명 정확히 확인후 적어주세요>\nex) 하기스 매직컴포트 팬티 5단계 등\n13. 가정(자녀방 등) 공개 및 기저귀 교체하는 과정 등을 촬영하는 방식하여 모든 조사방식에 동의하시나요? <YES만 가능>\n14. 11월 4일(수)에 인터뷰 진행가능한 시간을 적어주세요. <120분 소요>\nex) 10시~14시 모두 가능, 11시-13시 또는 14시-18시 가능, 15시 이후 모두 가능 등\n** 조사방식을 모두 준수하실 수 있는 분들의 많은 신청바랍니다.\nhttps://forms.gle/Bfcvm5Xh7kRdQGML8\n좋아요\n0\n송파구에서 핫한 진짜 동네 이야기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n9-16kg, 4-5단계 팬티형 기저귀 사용하는 여아 자녀와 어머님 대상 [가정방문 인터뷰] 모집(*11/4 진행)\n좌담회알바좌담회카페\n26.10.22.\n댓글\n0\n9-16kg, 4-5단계 팬티형 기저귀 사용하는 남아 자녀와 어머님 대상 [가정방문 인터뷰] 모집(*11/4 진행)\n좌담회알바좌담회카페\n26.10.22.\n댓글\n0\n10/23) 의류관리기 (에어드레서) 구독 관련 좌담회\n좌담회알바좌담회카페\n26.10.22.\n댓글\n0\n10/23) 공기청정기 구독 관련 좌담회\n좌담회알바좌담회카페\n26.10.22.\n댓글\n0\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588",
